// intl.h — data tables for the Intl builtins. The tables live in intl_data.c
// (generated by tools/gen_intl.py from CLDR JSON — third-party data under the
// Unicode License, the same class as unicode_data.c); the runtime that walks
// them lives in intl.c, the JS surface in b_intl.c.
#ifndef OJS_INTL_H
#define OJS_INTL_H

// the table part of this header is standalone C (intl_data.c includes it
// as-is); the runtime declarations need the engine's value type
#include "ojs_int.h"

// all strings below are offsets into intl_pool (UTF-8, NUL-terminated)
extern const char intl_pool[];

// one covered locale (sorted by tag; lookup is binary search)
struct intl_loc {
    const char* tag;
    unsigned char nu;               // default numbering system (intl_nsys index)
    unsigned char hc;               // default hour cycle: 0 h11, 1 h12, 2 h23, 3 h24
    unsigned char hg;               // minimumGroupingDigits
    unsigned char pad;
    unsigned sym[8];                // decimal group percentSign plusSign minusSign exponential perMille list
    unsigned dec, pct, sci, cur;    // standard decimal / percent / scientific / currency patterns
    unsigned short card, ord;       // cardinal / ordinal plural ruleset (intl_rs, 0xFFFF none)
    unsigned short comp_s, comp_l;  // compact groups, 13 consecutive (10^3..10^15), short/long
    unsigned mo[6];                 // months: format wide/abbrev/narrow, stand-alone wide/abbrev/narrow (12 each)
    unsigned dy[4];                 // days: format wide/abbrev/narrow, stand-alone wide (7 each, sun first)
    unsigned per;                   // day periods: am pm noon midnight
    unsigned era;                   // eras: BC AD (abbr), BC AD (wide)
    unsigned df, tf, glue;          // date/time/glue patterns: full long medium short
    unsigned short af_off, af_n;    // availableFormats: (skel, pat) u16 pairs in intl_af
    unsigned short cur_off, cur_n;  // currencies (intl_lcur, sorted by code)
    unsigned short unit_off, unit_n;// units (intl_lunit, sorted by unit)
    unsigned short lp;              // listPatterns: 5 groups x 4 offsets in intl_lp (0xFFFF none)
    unsigned short fld;             // date fields: 8 x 3 intl_fgrp (0xFFFF none)
};

struct intl_rset { unsigned short mask, off, n; };  // plural rules: bit i = category i present
struct intl_cpair { unsigned char cat; unsigned pat; };   // pat: pool offset (exceeds 16 bits)
struct intl_cgrp { unsigned short off, n; };
struct intl_nsys { const char* id; const char* digits; };
struct intl_likely { const char* src, *dst; };
struct intl_alias { const char* from, *to; };
struct intl_curfrac { const char* code; unsigned char digits; };
struct intl_lcur { unsigned code4; unsigned sym, narrow, name; unsigned short grp; };  // code4: ISO code packed 3 chars
struct intl_lunit { unsigned char ui; unsigned disp; unsigned short grp, sgrp; };
struct intl_fgrp { unsigned rel[3]; unsigned short fut, fut_n, past, past_n; };

extern const struct intl_loc intl_locales[];
extern const char* const intl_skel[];
extern const unsigned intl_af[];        // (skel, pattern) pairs — pool offsets exceed 16 bits
extern const struct intl_rset intl_rs[];
extern const unsigned intl_rs_off[];
extern const struct intl_cpair intl_cp[];
extern const struct intl_cgrp intl_cg[];
extern const struct intl_nsys intl_nsys[];
extern const struct intl_likely intl_likely[];
extern const struct intl_alias intl_alias_lang[], intl_alias_terr[], intl_alias_scr[];
extern const struct intl_curfrac intl_curfrac[];
extern const struct intl_lcur intl_lcur[];
extern const struct intl_lunit intl_lunit[];
extern const char* const intl_unit_id[];
extern const struct intl_fgrp intl_fg[];
extern const unsigned intl_lp[];

#define INTL_CURFRAC_DEFAULT 2
extern const unsigned intl_nloc, intl_nsys_n, intl_nskel_n, intl_nrs_n, intl_nunit_n,
    intl_ncp, intl_ncg, intl_nlikely, intl_nalias_lang, intl_nalias_terr, intl_nalias_scr,
    intl_ncurfrac, intl_nlcur, intl_nlunit, intl_nfg, intl_naf, intl_nlp;

#define intl_pool_at(off) (intl_pool + (off))
#define IP(off) intl_pool_at(off)

// option readers (intl.c); -1 return = exception pending
struct obj;
int  intl_opts_obj(ojs* J, jv opts, struct obj** out);
int  intl_opt_bool(ojs* J, struct obj* o, const char* name, int def, int* out);
int  intl_opt_num(ojs* J, struct obj* o, const char* name, double lo, double hi, int* out);
int  intl_opt_enum(ojs* J, struct obj* o, const char* name, const char* const* vals, int nvals, int def, int* out);
int  intl_opt_str(ojs* J, struct obj* o, const char* name, jv* out);
int  intl_opt_cstr(ojs* J, struct obj* o, const char* name, char* buf, unsigned cap);

// ---------------------------------------------------------------- runtime (intl.c)

// tags
int  intl_canonicalize(const char* src, unsigned len, char* out, unsigned cap); // 0 ok, -1 invalid
int  intl_maximize(const char* tag, unsigned len, char* out, unsigned cap);
int  intl_minimize(const char* tag, unsigned len, char* out, unsigned cap);
int  intl_lookup_locale(const char* tag, unsigned len);        // exact data index, -1
const char* intl_loc_tag(unsigned li);
int  intl_resolve(const char* tag, unsigned len);              // best data locale (en fallback)
int  intl_tag_keyword(const char* tag, const char* key, char* out, unsigned cap);

// plural rules; category 0..4 = zero/one/two/few/many, 5 = other
int  intl_plural_select(unsigned rs, double x);
const char* intl_plural_cat_name(int cat);
int  intl_plural_cat_index(const char* name);

// rounding modes (Intl.NumberFormat roundingMode)
enum { RM_CEIL, RM_FLOOR, RM_EXPAND, RM_TRUNC, RM_HALF_CEIL, RM_HALF_FLOOR,
       RM_HALF_EXPAND, RM_HALF_TRUNC, RM_HALF_EVEN };
int  intl_exact_digits(double x, char* out, int cap, int* point);  // 0.digits * 10^point

// number formatting
struct intl_nfmt {
    const char* pat_dec;                  // CLDR patterns (pool text)
    const char* pat_pct;
    const char* pat_cur;
    unsigned sym[8];                      // decimal group percentSign plusSign minusSign exponential perMille list
    short min_int;                        // >= 0
    short min_frac, max_frac, min_sig, max_sig;   // -1 = pattern default / unset
    unsigned char mode;                   // RM_*
    unsigned char use_grp;                // 1 = grouping on
    unsigned char sign_disp;              // 0 auto 1 never 2 always 3 exceptZero 4 negative
    unsigned char style;                  // 0 decimal 1 percent 2 currency 3 unit
    unsigned char notation;               // 0 standard 1 scientific 2 engineering 3 compact
    unsigned char compact_long;
    unsigned char cur_disp;               // 0 code 1 symbol 2 narrowSymbol 3 name
    unsigned char unit_disp;              // 0 long 1 short 2 narrow
    unsigned char nu;                     // numbering system for digit remap
    short cur_ci;                         // intl_curfrac index, -1 unknown
    short unit_ui;                        // intl_unit_id index, -1
    unsigned short card;                  // cardinal plural ruleset
    unsigned short comp_base;             // compact group base (short or long)
    unsigned short cur_entry;             // intl_lcur absolute index, 0xFFFF none
    unsigned short unit_entry;            // intl_lunit absolute index, 0xFFFF none
    const char* cur_code;                 // ISO code text (used for curDisplay "code")
};
struct ojsv;
jv   intl_nf_format(ojs* J, const struct intl_nfmt* f, double x, int want_parts);

// date formatting
struct intl_dfmt {
    unsigned short li;                    // data locale
    const char* date_pat;                 // CLDR pattern text, 0 = absent
    const char* time_pat;
    const char* glue;                     // "{1} {0}" style glue
    unsigned char tz;                     // 0 = UTC, 1 = local
    unsigned char nu;                     // numbering system for digit remap
    unsigned char wk_len;                 // requested weekday width in pattern terms (0 = none)
    unsigned char frac_add;               // append .SSS after the time pattern
    unsigned char tz_add;                 // append the zone name after the time pattern
    unsigned char tz_len;                 // z (1) or zzzz (4) for tz_add
};
jv   intl_df_format(ojs* J, struct intl_dfmt* f, double t, int want_parts);

// component codes for pattern selection: 0 absent, 1 numeric, 2 two-digit,
// 3 long, 4 short, 5 narrow; frac = 1..3 (fractionalSecondDigits)
struct intl_dtcomp {
    unsigned char weekday, era, year, month, day, dayperiod, hour, minute, second, tzname;
    unsigned char frac;
    unsigned char hc;                     // resolved hour cycle 0..3
};
int intl_dt_pick(unsigned short li, int date_style, int time_style,
                 const struct intl_dtcomp* c, const char** dp, const char** tp, const char** glue);

// relative time format: field 0..7 = year quarter month week day hour minute second
jv   intl_rtf_format(ojs* J, unsigned short li, int field, int width, int numeric,
                     double value, int want_parts);

// round x (halfExpand, Intl defaults) to a fraction-digit window
double intl_round_number(double x, int min_frac, int max_frac);

#endif
